@app.post("/orders/{order_id}/ship")
async def ship(order_id: str, body: ShipBody):
    row = repo.get(order_id)
    if row is None:
        raise HTTPException(status_code=404)
    if row["status"] != "paid":
        raise HTTPException(status_code=409, detail="not paid")
    repo.mark_shipped(order_id)
    return {"id": order_id, "status": "shipped"}

